program2='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    # Color 5 is the tile background. In some instances, 0 is also random
    # background noise; treat it as background when it is common.
    background = {5}
    if counts[0] > h * w * 0.10:
        background.add(0)
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            colors = {
                grid[r][c]
                for r in range(br * 3, br * 3 + 3)
                for c in range(bc * 3, bc * 3 + 3)
                if grid[r][c] not in background
            }
            if len(colors) == 1:
                out[br][bc] = next(iter(colors))
    return out
'''
